input.sparql:
SELECT ?entity WHERE {
  ?entity a brick:Zone .
  ?entity rdfs:label ?label .
  FILTER(CONTAINS(LCASE(?label), "basement"))
  ?entity brick:hasProperty ?p .
}

SELECT ?entity ?type WHERE {
  ?entity a ?type .
  FILTER(LCASE(STR(?type)) LIKE "%zone%")
} LIMIT 50

SELECT ?point ?class WHERE {
  ?point a ?class .
  FILTER(LCASE(STR(?class)) LIKE "%zone%")
} LIMIT 100

SELECT ?entity ?type ?label WHERE {
  ?entity a ?type .
  OPTIONAL { ?entity rdfs:label ?label . }
} LIMIT 200

SELECT ?s ?p ?o WHERE {
  ?s brick:isPointOf ?o .
  FILTER(?s a brick:Electric_Power_Sensor)
} LIMIT 200

